	s.Enqueue(models.Job{ID: "odd-1", Kind: "reboot", DeviceID: "dev-9", Tenant: "t1"})
	s.Run(ctx)
	s.Wait()

	if s.Completed() != 2 {
		t.Fatalf("Completed = %d, want 2", s.Completed())
	}
	if s.Failed() != 1 {
		t.Fatalf("Failed = %d, want 1", s.Failed())
	}
}

